export type TranslationKey = keyof typeof dictionaries['pt-BR'];
export type Translator = (key: TranslationKey, vars?: Record<string,string|number>) => string;

export function createTranslator(locale: Locale): Translator {
  return (key, vars = {}) => {
    let value: string = dictionaries[locale][key] ?? dictionaries['pt-BR'][key];
    for (const [name,replacement] of Object.entries(vars)) value=value.replaceAll(`{${name}}`,String(replacement));
    return value;
  };
}
